from builtins import object
from taf.ul.trs_e2e_fw.lib.remote_connection.ssh_library.ssh_controller import SshController
from taf.ul.trs_e2e_fw.lib.remote_connection.telnet_library.telnet_controller import \
    TelnetController
# from taf.ul.trs_e2e_fw.lib.remote_connection.ute_fsmaccess.ute_controller import UteController
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class Controller(object):
    session_type = None

    def __init__(self):
        # self.ute_fsm = UteController()
        self.telnet_conn = TelnetController()
        self.ssh_conn = SshController()

    def create_session_with_host(self, host_details, alias, timeout=30):
        """
            Creates a session with the host, specified by host_details
            @param host_details: dict, connection details to the host
            @param timeout:int, execution timeout. Default 30
            @param alias: string, Execution context
            @return:
            @raise
                From Telnet library : Exception
                From SSH library : SSHException
                UTE FSM : Exception from ute_fsmaccess library
        """
        host_details["session_type"] = "SSH" if not host_details.get("session_type") else \
            host_details.get(
            "session_type")
        Controller.session_type = host_details["session_type"]
        logger.debug("setting the session type {}".format(self.session_type))
        # if host_details.get("session_type").upper() == "FSM":
        #     self.ute_fsm.establish_connection_with_host_via_fsmaccess(host_details, alias)
        if host_details.get("session_type").upper() == "TELNET":
            self.telnet_conn.establish_telnet_connection_with_host(host_details, timeout, alias)
        elif host_details.get("session_type").upper() == "SSH":
            self.ssh_conn.establish_ssh_connection_with_host(host_details, timeout, alias)
        else:
            logger.error("Invalid session type entered :: {0}".format(host_details.get("session_type").upper()))

    def execute_command_on_host(self, command, return_rc, alias, pty):
        """
           Executes given command on the session specified by the alias
           @param command: string, command to be executed.
           @param return_rc: bool, Flag for returning shell command rc.
           @param alias: string, Execution context.
           @param pty: (Boolean) : True or False
           @return: Returns string or tuple depending on the parameter passed
            1. string, Shell command output.
            2. (string, int), If return_rc is True, also returns shell command rc.
           @raise
                From Telnet library : Exception
                From SSH library : SSHException
                UTE FSM : Exception from ute_fsmaccess library
        """
        # if self.session_type.upper() == "FSM":
        #     return self.ute_fsm.execute_command_on_host_using_ute_fsmaccess(command,
                                                                            # return_rc, alias)
        if self.session_type.upper() == "TELNET":
            prompt = self.telnet_conn.store.get(alias).get("prompt", "#")
            return self.telnet_conn.execute_command_on_host(command=command, prompt=prompt,
                                                            alias=alias)
        elif self.session_type.upper() == "SSH":
            return self.ssh_conn.execute_command(command=command, alias=alias, return_rc=return_rc, pty=pty)
            # if return_rc:
            #     return self.ssh_conn.execute_command(command=command, alias=alias)
            # else:
            #     return self.ssh_conn.execute_command_on_shell(command=command, alias=alias)

    def close_session_with_host(self, alias='default'):
        """
           Close session specified by the alias
           @param alias: string, Execution context. Default 'default'.
           @return:
           @raise
                From Telnet library : Exception
                From SSH library : SSHException
                UTE FSM : Exception from ute_fsmaccess library
        """
        # if self.session_type.upper() == "FSM":
        #     self.ute_fsm.close_fsm_session_with_host(alias)
        if self.session_type.upper() == "SSH":
            self.ssh_conn.close_ssh_session_with_host(alias)
        elif self.session_type.upper() == "TELNET":
            self.telnet_conn.close_telnet_session_with_host(alias)

    def get_file_from_host(self, source, destination, alias="default"):
        """
            Copies a file from given source as specified by the alias to destination on the local
            machine.
            @param source: string, source path
            @param destination: string, destination path
            @param alias: string, Execution context. Default 'default'
            @return: string, Destination path.
            @raise 	Exception raised from ute_fsmaccess library
        """
        # if self.session_type.upper() == "FSM":
        #     self.ute_fsm.get_file_from_host(source, destination, alias=alias)
        if self.session_type.upper() == "SSH":
            return self.ssh_conn.get_file_from_host(source, destination, alias)
            # logger.error("Not yet implemented for SSH")
        elif self.session_type.upper() == "TELNET":
            logger.error("Not yet implemented for TELNET")

    def put_file_on_host(self, source, destination, alias="default"):
        """
            Copies a file from given source on the local machine to destination path on the host
            specified by alias
            @param source: string, source path
            @param destination: string, destination path
            @param alias: string, Execution context. Default 'default'
            @return: string, Source file path.
            @raise 	Exception raised from ute_fsmaccess library
        """
        # if self.session_type.upper() == "FSM":
        #     self.ute_fsm.put_file_on_host(source, destination, alias=alias)
        if self.session_type.upper() == "SSH":
            return self.ssh_conn.put_file_on_host(source, destination, alias)
            # logger.error("Not yet implemented for SSH")
        elif self.session_type.upper() == "TELNET":
            logger.error("Not yet implemented for TELNET")

    def execute_command_on_shell(self, command, alias, exit_prompt='$', timeout=5, return_rc=False):
        """
            Executes command on ssh shell with reference to given alias
            @param command: string, command to execute
            @param alias: string, Execution context
            @param exit_prompt: string, expected prompt after executing given command
            @param return_rc: bool, returns error output
            @param timeout: int, execution timeout. Default 10
            @return: response received from the channel
            @raise 	SSHException: raises an exception
        """
        # if self.session_type.upper() == "FSM":
        #     logger.warn("Execute command on shell is not yet supported for FSM")
        if self.session_type.upper() == "SSH":
            return self.ssh_conn.execute_command_on_shell(command=command, alias=alias, exit_prompt=exit_prompt,
                                                          timeout=timeout, return_rc=return_rc)
        elif self.session_type.upper() == "TELNET":
            logger.warn("Execute command on shell is not yet supported for TELNET")

    def connect_to_hop(self, command, alias, password=None, prompt='$'):
        """
            Connect to hop
            @param command: string, command to execute.
            @param alias: string, Execution context.
            @param password: string, password. Default 'None', if password is not required.
            @param prompt: string, send expected prompt. Default '$'.
            @return:
            @raise 	SSHException, Exception: raises an exception
        """
        # if self.session_type.upper() == "FSM":
        #     logger.warn("Connect to hop is not yet supported for FSM")
        if self.session_type.upper() == "SSH":
            return self.ssh_conn.connect_to_hop(command=command, alias=alias, password=password, prompt=prompt)
        elif self.session_type.upper() == "TELNET":
            logger.warn("Connect to hop is not applicable for TELNET")

    def exit_from_hop_connection(self, alias):
        """
            This method exits from the SSH connection specified by alias. This is most used to exit
            multiple/double ssh connections by specifying its alias created during setup method
            @param alias: string, Execution context.
            @return:
            @raise
                From SSH library : SSHException
        """
        if self.session_type.upper() == "SSH":
            return self.ssh_conn.exit_from_hop_connection(alias)
        # elif self.session_type.upper() == "FSM":
        #     logger.warn("'exit from hop connection' is not yet supported for FSM session")
        elif self.session_type.upper() == "TELNET":
            logger.warn("'exit from hop connection' is not valid for Telnet session")

    def close_connection(self, alias):
        """Closes an open connection with reference to given alias
        @param alias: string, Execution context.
        @raise 	KeyError: raises an exception"""
        # if self.session_type.upper() == "FSM":
        #     self.ute_fsm.close_fsm_session_with_host(alias=alias)
        if self.session_type.upper() == "SSH":
            self.ssh_conn.close_ssh_session_with_host(alias=alias)
        elif self.session_type.upper() == "TELNET":
            self.telnet_conn.close_telnet_session_with_host(alias=alias)
